import cfnresponse
import time

def handler(event, context):
    try:
        if event['RequestType'] in ['Create', 'Update']:
            iam = boto3.client('iam')
            try:
                iam.create_service_linked_role(
                    AWSServiceName='ecs.amazonaws.com',
                    Description='ECS Service Linked Role'
                )
                print('Created ECS service-linked role')
            except iam.exceptions.InvalidInputException as e:
                if 'has been taken in this account' in str(e):
                    print('ECS service-linked role already exists')
                else:
                    raise
            # Wait 60 seconds for role to propagate
            print('Waiting 60 seconds for role to propagate...')
            time.sleep(60)
            print('Role propagation wait complete')
        cfnresponse.send(event, context, cfnresponse.SUCCESS, {})
    except Exception as e:
        print(f'Error: {str(e)}')
        cfnresponse.send(event, context, cfnresponse.FAILED, {})

