// This function is based on the cfnresponse JS module that is published
// by CloudFormation. It's an async function that makes coding much easier.
const respond = async function(event, context, responseStatus, responseData, physicalResourceId, noEcho) {
  return new Promise((resolve, reject) => {
    var responseBody = JSON.stringify({
        Status: responseStatus,
        Reason: "See the details in CloudWatch Log Stream: " + context.logGroupName + " " + context.logStreamName,
        PhysicalResourceId: physicalResourceId || context.logStreamName,
        StackId: event.StackId,
        RequestId: event.RequestId,
        LogicalResourceId: event.LogicalResourceId,
        NoEcho: noEcho || false,
        Data: responseData
    });

    console.log("Response body:\\n", responseBody);

    var https = require("https");
    var url = require("url");

    var parsedUrl = url.parse(event.ResponseURL);
    var options = {
        hostname: parsedUrl.hostname,
        port: 443,
        path: parsedUrl.path,
        method: "PUT",
        headers: {
            "content-type": "",
            "content-length": responseBody.length
        }
    };

    var request = https.request(options, function(response) {
        console.log("Status code: " + response.statusCode);
        console.log("Status message: " + response.statusMessage);
        resolve();
    });

    request.on("error", function(error) {
        console.log("respond(..) failed executing https.request(..): " + error);
        resolve();
    });

    request.write(responseBody);
    request.end();
  });
};
const {
  S3Client,
  ListObjectVersionsCommand,
  DeleteObjectsCommand,
} = require('@aws-sdk/client-s3');

exports.handler = async function (event, context) {
  console.log(JSON.stringify(event, null, 4));
  const bucketName = event.ResourceProperties.BucketName;

  try {
    if (event.RequestType === 'Delete') {
      const s3 = new S3Client({});
      let keyMarker;
      let versionIdMarker;
      let isTruncated = true;

      while (isTruncated) {
        const result = await s3.send(new ListObjectVersionsCommand({
          Bucket: bucketName,
          KeyMarker: keyMarker,
          VersionIdMarker: versionIdMarker,
        }));

        const objects = [...(result.Versions || []), ...(result.DeleteMarkers || [])]
          .map(({ Key, VersionId }) => ({ Key, VersionId }));

        if (objects.length > 0) {
          await s3.send(new DeleteObjectsCommand({
            Bucket: bucketName,
            Delete: { Objects: objects, Quiet: true },
          }));
        }

        isTruncated = result.IsTruncated;
        keyMarker = result.NextKeyMarker;
        versionIdMarker = result.NextVersionIdMarker;
      }
    }

    await respond(event, context, 'SUCCESS', {}, bucketName);
  } catch (error) {
    console.error(error);
    await respond(event, context, 'FAILED', { Error: String(error) }, bucketName);
  }
};
